<?php
declare(strict_types=1);
require __DIR__ . '/relay.php';
header('Cache-Control: no-store'); header('Referrer-Policy: no-referrer');
header("Content-Security-Policy: default-src 'none'; style-src 'unsafe-inline'; form-action 'self'; frame-ancestors 'none'; base-uri 'none'");
header('X-Content-Type-Options: nosniff');
if (is_file(__DIR__ . '/config.php')) { http_response_code(403); exit('نصب انجام شده است. تنظیمات را در config.php ویرایش کنید و installer.php را حذف کنید.'); }
$https = !empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off';
if (!$https && !in_array($_SERVER['REMOTE_ADDR'] ?? '', ['127.0.0.1','::1'], true)) { http_response_code(403); exit('ابتدا HTTPS دامنه را فعال کنید.'); }
session_start(['cookie_httponly'=>true, 'cookie_secure'=>$https, 'cookie_samesite'=>'Strict']);
$_SESSION['csrf'] ??= bin2hex(random_bytes(32));
function esc(mixed $value): string { return htmlspecialchars((string)$value, ENT_QUOTES, 'UTF-8'); }
$error = ''; $success = false;
$ready = version_compare(PHP_VERSION, '8.1', '>=') && extension_loaded('curl') && is_writable(__DIR__);
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    try {
        if (!hash_equals($_SESSION['csrf'], (string)($_POST['csrf'] ?? ''))) throw new RuntimeException('صفحه را تازه کنید و دوباره تلاش کنید.');
        if (!isset($_SESSION['authorized'])) {
            $keyFile = __DIR__ . '/setup-key.php';
            $key = is_file($keyFile) ? require $keyFile : '';
            if (!is_string($key) || strlen($key) < 24 || str_contains($key, 'REPLACE_') || !hash_equals($key, (string)($_POST['key'] ?? ''))) throw new RuntimeException('کلید نصب صحیح نیست؛ setup-key.php را مطابق راهنما بسازید.');
            session_regenerate_id(true); $_SESSION['authorized'] = true;
        } elseif (($_POST['action'] ?? '') === 'review') {
            if (!$ready) throw new RuntimeException('پیش‌نیازهای PHP، cURL و مجوز نوشتن را بررسی کنید.');
            $mode = (string)($_POST['mode'] ?? '');
            $config = relay_config([
                'public_url' => trim((string)($_POST['public_url'] ?? '')), 'mode' => $mode,
                'panels' => ['marzban'=>trim((string)($_POST['marzban'] ?? '')), 'pasarguard'=>trim((string)($_POST['pasarguard'] ?? ''))],
                'order' => $mode === 'dual' ? ['marzban','pasarguard'] : [$mode],
                'connect_timeout' => (int)($_POST['connect_timeout'] ?? 5), 'timeout' => (int)($_POST['timeout'] ?? 20),
            ]);
            $checks = [];
            foreach ($config['order'] as $panel) {
                $probe = relay_request($config['panels'][$panel] . '/subrelay-install-probe-' . bin2hex(random_bytes(12)), $config, ['User-Agent: SubRelay-Installer/0.1']);
                if ($probe['error'] || $probe['status'] >= 300 && $probe['status'] < 400 || $probe['status'] >= 500) throw new RuntimeException('اتصال یا TLS پنل ' . $panel . ' مشکل دارد؛ آدرس نهایی /sub و پورت خروجی را بررسی کنید.');
                $checks[$panel] = $probe['status'];
            }
            $_SESSION['pending'] = $config; $_SESSION['checks'] = $checks;
        } elseif (($_POST['action'] ?? '') === 'save') {
            if (!isset($_SESSION['pending'])) throw new RuntimeException('ابتدا تنظیمات را بررسی کنید.');
            $config = relay_config($_SESSION['pending']);
            $lock = fopen(__DIR__ . '/install.lock', 'c');
            if (!$lock || !flock($lock, LOCK_EX)) throw new RuntimeException('قفل نصب ایجاد نشد.');
            try {
                if (file_exists(__DIR__ . '/config.php')) throw new RuntimeException('تنظیمات قبلاً ایجاد شده‌اند.');
                $file = fopen(__DIR__ . '/config.php', 'x');
                if (!$file) throw new RuntimeException('امکان ساخت config.php نیست.');
                $data = "<?php\n// Generated by SubRelay. Edit this file to change relay settings.\nreturn " . var_export($config, true) . ";\n";
                $written = fwrite($file, $data); fclose($file);
                if ($written !== strlen($data)) { unlink(__DIR__ . '/config.php'); throw new RuntimeException('ذخیره تنظیمات کامل نشد.'); }
                chmod(__DIR__ . '/config.php', 0600);
                $success = true; $_SESSION = []; session_destroy();
            } finally { flock($lock, LOCK_UN); fclose($lock); }
        } elseif (($_POST['action'] ?? '') === 'edit') { unset($_SESSION['pending']); }
    } catch (Throwable $e) { $error = $e->getMessage(); }
}
?>
